function S({registerIndicator:p,rollingSum:M,nulls:y}){p({id:"oa-massi",name:"Mass Index (MASSI)",category:"Volatility",placement:"pane",inputs:[{key:"emaLength",type:"number",label:"EMA Length",default:9,min:1,max:5e3,step:1,tooltip:"Period for EMA smoothing of high-low range"},{key:"sumLength",type:"number",label:"Sum Length",default:25,min:1,max:5e3,step:1,tooltip:"Period for summing the EMA ratio"}],plots:[{key:"massi",type:"line",title:"MASSI",style:{color:"#ffeb3b",lineWidth:2}}],calc(o,m){const b=Math.max(1,Math.floor(Number(m.emaLength)||9)),d=Math.max(1,Math.floor(Number(m.sumLength)||25)),l=o.length,r=new Array(l).fill(0),a=2/(b+1),L=1-a;let s=!0,i=1,e=0,n=0;for(let t=0;t<l;t++){const h=o[t].high,c=o[t].low,x=Number.isFinite(h)&&Number.isFinite(c)?h-c:0;e=a*(x-e)+e,n=a*(e-n)+n,s&&(i*=L,s=i>1e-10);const u=1-i,g=s&&u>0?1/u:1,A=g*e,f=g*n;r[t]=f!==0?A/f:0}const w=M(r,d);return{massi:y(w)}}})}export{S as default};
